202|void
203|BootstrapModeMain(int argc, char *argv[], bool check_only)
204|{
205|	int			i;
206|	char	   *progname = argv[0];
207|	int			flag;
208|	char	   *userDoption = NULL;
209|
210|	Assert(!IsUnderPostmaster);
211|
212|	InitStandaloneProcess(argv[0]);
213|
214|	/* Set defaults, to be overridden by explicit options below */
215|	InitializeGUCOptions();
216|
217|	/* an initial --boot or --check should be present */
218|	Assert(argc == 1
219|		   || strcmp(argv[1], "--boot") != 0
220|		   || strcmp(argv[1], "--check") != 0);
221|	argv++;
222|	argc--;
223|
224|	while ((flag = getopt(argc, argv, "B:c:d:D:Fkr:X:-:")) != -1)
225|	{
226|		switch (flag)
227|		{
228|			case 'B':
229|				SetConfigOption("shared_buffers", optarg, PGC_POSTMASTER, PGC_S_ARGV);
230|				break;
231|			case 'D':
232|				userDoption = pstrdup(optarg);
233|				break;
234|			case 'd':
235|				{
236|					/* Turn on debugging for the bootstrap process. */
237|					char	   *debugstr;
238|
239|					debugstr = psprintf("debug%s", optarg);
240|					SetConfigOption("log_min_messages", debugstr,
241|									PGC_POSTMASTER, PGC_S_ARGV);
242|					SetConfigOption("client_min_messages", debugstr,
243|									PGC_POSTMASTER, PGC_S_ARGV);
244|					pfree(debugstr);
245|				}
246|				break;
247|			case 'F':
248|				SetConfigOption("fsync", "false", PGC_POSTMASTER, PGC_S_ARGV);
249|				break;
250|			case 'k':
251|				bootstrap_data_checksum_version = PG_DATA_CHECKSUM_VERSION;
252|				break;
253|			case 'r':
254|				strlcpy(OutputFileName, optarg, MAXPGPATH);
255|				break;
256|			case 'X':
257|				{
258|					int			WalSegSz = strtoul(optarg, NULL, 0);
259|
260|					if (!IsValidWalSegSize(WalSegSz))
261|						ereport(ERROR,
262|								(errcode(ERRCODE_INVALID_PARAMETER_VALUE),
263|								 errmsg("-X requires a power of two value between 1 MB and 1 GB")));
264|					SetConfigOption("wal_segment_size", optarg, PGC_INTERNAL,
265|									PGC_S_OVERRIDE);
266|				}
267|				break;
268|			case 'c':
269|			case '-':
270|				{
271|					char	   *name,
272|							   *value;
273|
274|					ParseLongOption(optarg, &name, &value);
275|					if (!value)
276|					{
277|						if (flag == '-')
278|							ereport(ERROR,
279|									(errcode(ERRCODE_SYNTAX_ERROR),
280|									 errmsg("--%s requires a value",
281|											optarg)));
282|						else
283|							ereport(ERROR,
284|									(errcode(ERRCODE_SYNTAX_ERROR),
285|									 errmsg("-c %s requires a value",
286|											optarg)));
287|					}
288|
289|					SetConfigOption(name, value, PGC_POSTMASTER, PGC_S_ARGV);
290|					free(name);
291|					if (value)
292|						free(value);
293|					break;
294|				}
295|			default:
296|				write_stderr("Try \"%s --help\" for more information.\n",
297|							 progname);
298|				proc_exit(1);
299|				break;
300|		}
301|	}
302|
303|	if (argc != optind)
304|	{
305|		write_stderr("%s: invalid command-line arguments\n", progname);
306|		proc_exit(1);
307|	}
308|
309|	/* Acquire configuration parameters */
310|	if (!SelectConfigFiles(userDoption, progname))
311|		proc_exit(1);
312|
313|	/*
314|	 * Validate we have been given a reasonable-looking DataDir and change
315|	 * into it
316|	 */
317|	checkDataDir();
318|	ChangeToDataDir();
319|
320|	CreateDataDirLockFile(false);
321|
322|	SetProcessingMode(BootstrapProcessing);
323|	IgnoreSystemIndexes = true;
324|
325|	InitializeMaxBackends();
326|
327|	BaseInit();
328|
329|	/*
330|	 * XXX: It might make sense to move this into its own function at some
331|	 * point. Right now it seems like it'd cause more code duplication than
332|	 * it's worth.
333|	 */
334|	if (check_only)
335|	{
336|		SetProcessingMode(NormalProcessing);
337|		CheckerModeMain();
338|		abort();
339|	}
340|
341|	bootstrap_signals();
342|	BootStrapXLOG();
343|
344|	/*
345|	 * To ensure that src/common/link-canary.c is linked into the backend, we
346|	 * must call it from somewhere.  Here is as good as anywhere.
347|	 */
348|	if (pg_link_canary_is_frontend())
349|		elog(ERROR, "backend is incorrectly linked to frontend functions");
350|
351|	/*
352|	 * Do backend-like initialization for bootstrap mode
353|	 */
354|	InitProcess();
355|
356|	InitPostgres(NULL, InvalidOid, NULL, InvalidOid, NULL, false);
357|
358|	/* Initialize stuff for bootstrap-file processing */
359|	for (i = 0; i < MAXATTR; i++)
360|	{
361|		attrtypes[i] = NULL;
362|		Nulls[i] = false;
363|	}
364|
365|	/*
366|	 * Process bootstrap input.
367|	 */
368|	StartTransactionCommand();
369|	boot_yyparse();
370|	CommitTransactionCommand();
371|
372|	/*
373|	 * We should now know about all mapped relations, so it's okay to write
374|	 * out the initial relation mapping files.
375|	 */
376|	RelationMapFinishBootstrap();
377|
378|	/* Clean up and exit */
379|	cleanup();
380|	proc_exit(0);
381|}

